import{z as n,x as A,o as e,c as o,q as t,j as l,D as E,d as B,s,S as r}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"基线与优势函数","description":"","frontmatter":{"title":"基线与优势函数","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/baselines-advantage.md","filePath":"llm/baselines-advantage.md","lastUpdated":1791413859000}'),p={name:"llm/baselines-advantage.md"};function m(d,a,_,h,b,D){const i=A("Mermaid");return e(),o("div",null,[a[2]||(a[2]=t('<h1 id="基线与优势函数" tabindex="-1">基线与优势函数 <a class="header-anchor" href="#基线与优势函数" aria-label="Permalink to &quot;基线与优势函数&quot;">​</a></h1><div class="epigraph"><p>从回报里减掉一个只看状态、不看动作的数，期望纹丝不动，方差却大幅下降；剩下的那点差额，才配叫「优势」。</p><footer>—— 据 Williams, 1992；Greensmith, Barto &amp; Anderson, 2004；Sutton &amp; Barto, 2018 §13.4 整理</footer></div><p><a href="/llm/reinforce-variance">上一课</a>把方差拆成回报波动与得分范数的耦合项，批内标准化只是运气版的对策。缺口是要一个有原则的减法：减什么、为什么不会减坏、最优能减到哪。本课写基线定理——\\(b(s)\\) 不改期望只改方差；取 \\(b=V^{\\pi}\\) 得到优势函数 \\(A=Q-V\\)；再把这套语言对上 LLM 后训练里现成的组归一化基线（<a href="/llm/grpo">GRPO</a>）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的四件经验减缩里，标准化依赖同一批恰好采到什么，批间漂移没法控制；梯度裁剪有偏。想要的是逐状态的中心化：同一状态，有的轨迹走运、有的倒霉，这部分波动与「策略在该状态怎么选」无关，却全被乘进了梯度。问题因此精确化：找一个量 \\(b(s_t)\\) 从 \\(G_t\\) 里减掉，要求期望严格不变、方差尽量小。</p><p><span class="marginnote">可以把它想成考试划平均分：全班平均 72 分，你考 80 分，老师表扬的是高出的那 8 分，而不是 80 本身——这里的 72 就是基线，8 就是优势。同一个你在尖子班里可能只考 65 分、低于班均，绝对分数变了，但「比平均水平好多少」永远算得清，这才是真正要传递给学习算法的信号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>期望不变是恒等式的直接推论：\\(\\mathbb{E}_{a\\sim\\pi_\\theta}[b(s)\\nabla_\\theta\\log\\pi_\\theta(a\\mid s)]=b(s)\\sum_a\\nabla_\\theta\\pi_\\theta(a\\mid s)=b(s)\\,\\nabla_\\theta 1=0\\)。于是</p> \\[\\nabla_\\theta J=\\mathbb{E}\\bigl[(G_t-b(s_t))\\,\\nabla_\\theta\\log\\pi_\\theta(a_t\\mid s_t)\\bigr] \\]<p>对任何 \\(b(s)\\) 成立。方差是 \\(b\\) 的二次函数，逐状态求极小得最优基线 \\(b^{*}(s)=\\mathbb{E}[G_t\\lVert\\nabla\\log\\pi\\rVert^2\\mid s_t=s]/\\mathbb{E}[\\lVert\\nabla\\log\\pi\\rVert^2\\mid s_t=s]\\)；把得分范数的加权略去，它约等于 \\(\\mathbb{E}[G_t\\mid s_t=s]=V^{\\pi}(s)\\)。取 \\(b=V^{\\pi}\\)，权重变成</p> \\[A^{\\pi}(s,a)=Q^{\\pi}(s,a)-V^{\\pi}(s), \\]<p>优势：这个动作比该状态的平均水平好多少。它正是策略改进想要的量——好于平均就抬高，差于平均就压低，状态的运气被 \\(V\\) 吸收掉了。</p><p><span class="marginnote">初学者容易把优势为负读成「这个动作很糟」。它只说明该动作不如同一状态下的平均水平，绝对回报可能仍是正的；正优势也不保证动作完美，只说明它好过平均。信用分配比较的对象是「同状态下其他可选动作」，不是零分——这也是为什么换一个更难的场景，同一个动作的优势会整个翻号。</span></p>',13)),(e(),l(r,null,{default:E(()=>[s(i,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%9B%9E%E6%8A%A5%20Gt%22%5D%20--%3E%20SUB%5B%22%E5%87%8F%E5%8E%BB%E5%9F%BA%E7%BA%BF%20V(st)%22%5D%0A%20%20V%5B%22%E5%80%BC%E5%87%BD%E6%95%B0%20V(st)%22%5D%20--%3E%20SUB%0A%20%20SUB%20--%3E%20A%5B%22%E4%BC%98%E5%8A%BF%20A%20%3D%20Gt%20%E2%88%92%20V%22%5D%0A%20%20A%20--%3E%20W%5B%22%E5%8A%A0%E6%9D%83%E5%BE%97%E5%88%86%20grad%20log%20pi%22%5D%0A%20%20W%20--%3E%20UP%5B%22%E6%9B%B4%E6%96%B0%E7%AD%96%E7%95%A5%22%5D%0A%20%20G%20--%3E%20REG%5B%22%E5%9B%9E%E5%BD%92%E8%AE%AD%E7%BB%83%20V%22%5D%0A%20%20REG%20--%3E%20V%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">基线的合法条件是「与正在求导的那个动作独立」：可以依赖状态、依赖其他样本、甚至依赖 \\(\\theta\\)。同提示采 \\(G\\) 条完成、用组内均值当基线时，若自己的分数也漏进了均值与标准差（<a href="/llm/grpo">GRPO</a> 的组归一化正是如此），严格说已带一点偏差；留一均值的 <a href="/llm/rloo">RLOO</a> 是干净的版本。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>组归一化恰好是基线定理在 LLM 里的落地：同一 prompt 采一组完成，组均值当 \\(b\\)，组内相对名次当优势——不学任何价值网络。代价在时间结构：\\(V^{\\pi}(s_t)\\) 是逐状态基线，能区分同一序列里不同前缀的处境；组基线整条序列共用一个数，序列内部的好前缀与坏后缀仍然同赏同罚。标准差除法是尺度归一，超出定理允许的「减法」，好处是奖励量纲跨题可比，坏处是组内全对或全错时归一化没有信号。方差省了多少可以算：\\(\\{0,1\\}\\) 奖励、成功率 \\(p\\) 时，减去 \\(V\\approx p\\) 把权重二阶矩从 \\(p\\) 压到 \\(p(1-p)\\)——成功率越极端，相对收益越大。</p><p><span class="marginnote">代入数字感受一下：成功率 \\(p=0.5\\) 时，二阶矩从 \\(0.5\\) 压到 \\(0.5\\times(1-0.5)=0.25\\)，方差减半；\\(p=0.95\\) 时从 \\(0.95\\) 压到约 \\(0.0475\\)，缩到约二十分之一。任务越接近「全对或全错」的极端，减基线省下的方差越多——这也解释了可验证奖励任务上组归一化为什么格外划算。</span></p>',4)),(e(),l(r,null,{default:E(()=>[s(i,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%90%8C%E4%B8%80%20prompt%20%E9%87%87%20G%20%E6%9D%A1%E5%AE%8C%E6%88%90%22%5D%20--%3E%20AVG%5B%22%E7%BB%84%E5%9F%BA%E7%BA%BF%EF%BC%9A%E7%BB%84%E5%9D%87%E5%80%BC%E5%BD%93%20b%22%5D%0A%20%20AVG%20--%3E%20A1%5B%22%E4%B8%8D%E7%94%A8%E8%AE%AD%E7%BB%83%E4%BB%B7%E5%80%BC%E7%BD%91%E7%BB%9C%EF%BC%8C%E7%9C%81%E6%98%BE%E5%AD%98%22%5D%0A%20%20AVG%20--%3E%20A2%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E6%95%B4%E6%9D%A1%E5%BA%8F%E5%88%97%E5%85%B1%E7%94%A8%E4%B8%80%E4%B8%AA%E6%95%B0%22%5D%0A%20%20A2%20--%3E%20A3%5B%22%E5%BA%8F%E5%88%97%E5%86%85%E5%A5%BD%E5%89%8D%E7%BC%80%E4%B8%8E%E5%9D%8F%E5%90%8E%E7%BC%80%E5%90%8C%E8%B5%8F%E5%90%8C%E7%BD%9A%22%5D%0A%20%20V%5B%22%E9%80%90%E7%8A%B6%E6%80%81%E5%9F%BA%E7%BA%BF%EF%BC%9A%E6%AF%8F%E6%AD%A5%E4%B8%80%E4%B8%AA%20V(st)%22%5D%20--%3E%20B1%5B%22%E8%83%BD%E5%8C%BA%E5%88%86%E4%B8%8D%E5%90%8C%E5%89%8D%E7%BC%80%E7%9A%84%E5%A4%84%E5%A2%83%22%5D%0A%20%20V%20--%3E%20B2%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E8%A6%81%E8%AE%AD%E7%BB%83%20critic%EF%BC%8C%E6%9C%89%E6%98%BE%E5%AD%98%E4%B8%8E%E6%BB%9E%E5%90%8E%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>基线的收益取决于 \\(V\\) 估得多准：\\(V\\) 靠回归学，学坏了可能不如「减组均值」。\\(A=Q-V\\) 若两边都靠估计，误差相加而不相消——除非走自举的差分形式，让 \\(V\\) 的误差在差分里部分对消，那是下一课。逐状态基线要求学一个价值函数，显存与滞后都是成本；组基线要求同提示多采样，用生成预算换 critic。哪条划算取决于奖励噪声：可验证的 0/1 组内干净，噪声大的 RM 分数会被组内抖动放大，<a href="/llm/grpo">GRPO</a> 一课已把这条件写清。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>基线定理：\\(b(s)\\) 与动作独立则期望不变；方差是 \\(b\\) 的二次函数，存在最优值。</li><li>\\(b=V^{\\pi}\\) 给出优势 \\(A=Q-V\\)：把状态运气从信用分配里剥离。</li><li>合法条件是「不依赖当前动作」；自己的分数漏进基线会引入偏差，留一是干净版。</li><li>组归一化 = 基线定理的 LLM 批量实现：省 critic，付的是序列内时间结构。</li><li>出处：Williams, 1992；Greensmith, Barto &amp; Anderson, <em>Variance Reduction Techniques for Gradient Estimates in Reinforcement Learning</em>, JMLR 2004；Shao et al., DeepSeekMath, 2024。</li></ul>',4))])}const C=n(p,[["render",m]]);export{c as __pageData,C as default};
